--region private
function UIFastNettingFishingRewardDialog:InitData()
    self.rewards = checkTable(self.parameters.rewards)
    self.placeId = checkNumber(self.parameters.placeId)
    local recipeRewards = {}
    local newCount = 0
    if self.rewards then
        self.fishRewards = {}
        for _, reward in ipairs(self.rewards) do
            local goodsId = reward.goodsId
            local type = GoodsUtils.GetIdType(goodsId)
            if type == Constants.IDType.GoodsFish then
                local vo = FishingUtils.GetFishingSpeciesVo(goodsId)
                -- 是否为新鱼
                if reward.isNew then
                    newCount = newCount + 1
                end
                -- 是否为新菜谱
                if checkNumber(vo.unlock) > 0 then
                    --local foodVo = CookingUtils.GetBattleCookingFoodVo(vo.unlock)

                    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                    local dojo = maidCoffeePlayerComponent:GetRecipeDoJoById(vo.unlock)
                    local isHaveMenu = (dojo ~= nil)
                    if not isHaveMenu then
                        table.insert(recipeRewards, {
                            goodsId = vo.unlock,
                            num = 1
                        })
                        maidCoffeePlayerComponent:UpdateThingNo(vo.unlock)
                    end
                end

                table.insert(self.fishRewards, reward)
            end
        end
    end
    self:RefreshUI()
    GoodsUtils.DrawRewards(self.fishRewards)
    if table.count(recipeRewards) > 0 then
        self:DisplayNewRecipe(recipeRewards)
    end

    -- 更新图鉴数量
    FishingUtils.AddFishPlaceAtlasCollectNum(self.placeId, newCount)
end

---DisplayNewRecipe @ 展示新的食谱
function UIFastNettingFishingRewardDialog:DisplayNewRecipe(recipeRewards)
    self._showCo = cs_coroutine.start(function()
        for _, recipeReward in ipairs(recipeRewards) do
            cs_coroutine.yield_return(UIModule.OpenDialog({
                id = Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel,
                parameters = {
                    data = recipeReward,
                    levelUpType = Constants.UICultivateLevelUpFinishType.GetRecipe,
                    autoHide = true
                }
            }))
        end
        self._showCo = nil
    end)
end

function UIFastNettingFishingRewardDialog:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self.fishRewards[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type FastNettingRewardCell
    local scr = CfUtils.GetLuaScr(cell, "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFastNettingFishing.FastNettingRewardCell")
    scr:Refresh(cellData)
    return cell
end

function UIFastNettingFishingRewardDialog:RefreshUI()
    local count = table.count(self.fishRewards)
    CfUtils.FillText(self.TextTitle, localize("本次捕鱼获得以下奖励:"))

    if not self.RankingLoopView.IsListViewInit then
        self.RankingLoopView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.RewardLoopView, count)
    end
end
